# -*- coding: utf-8 -*-
"""Lote 1 · parte C: cardiología (hipertensión, shock, insuficiencia cardiaca, isquemia) e histología vascular."""
from lote01b import Q, L

Q(a="endocrinologia", cat=None, tema="Feocromocitoma: metanefrinas", año=2014, ext=False,
  e="Varón de 35 años que acude a emergencia con crisis hipertensivas a repetición. En una oportunidad presentó dolor abdominal por lo cual le solicitaron una TAC abdominal encontrándose una tumoración sobre el riñón izquierdo. ¿Qué examen se solicita para precisar el diagnóstico?",
  o=["Cortisol plasmático.", "Metanefrinas urinarias.", "Renina sérica.", "IGF-1.", "Aldosterona."], k="B",
  c="La hipertensión paroxística en un joven con una masa suprarrenal izquierda sugiere feocromocitoma, tumor productor de catecolaminas (tríada: cefalea, sudoración y palpitaciones). La prueba diagnóstica inicial recomendada por la Endocrine Society (2014, vigente en 2026) es la medición de metanefrinas fraccionadas libres en plasma o en orina de 24 horas, más sensibles (> 95 %) que las catecolaminas porque el tumor las produce de forma continua y no episódica. Luego se localiza con TC o RM. Antes de operar es obligatorio el bloqueo alfa (fenoxibenzamina o doxazosina) durante 10-14 días y después el betabloqueante: nunca betabloqueo solo, porque desenmascara la vasoconstricción alfa y puede precipitar una crisis. El cortisol, la aldosterona y la renina estudian el síndrome de Cushing y el hiperaldosteronismo.",
  f="Endocrine Society, feocromocitoma y paraganglioma (Lenders 2014); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Atenolol: antagonista beta", año=2014, ext=False,
  e="En la clasificación de antihipertensivos según el mecanismo de acción, el atenolol corresponde a un...",
  o=["Antagonista del receptor beta.", "Antagonista del receptor alfa.", "Agente adrenérgico con acción central.",
     "Antagonista mixto del receptor alfa y beta.", "Bloqueante de neuronas adrenérgicas."], k="A",
  c="El atenolol es un betabloqueante cardioselectivo (bloquea los receptores beta-1), hidrofílico y de eliminación renal. Reduce la frecuencia cardiaca, la contractilidad y la liberación de renina, de ahí su efecto antihipertensivo y antianginoso. Los fármacos terminados en «-olol» son betabloqueantes; el labetalol y el carvedilol son bloqueantes mixtos alfa y beta; la doxazosina y la prazosina son antagonistas alfa-1; la metildopa y la clonidina actúan de forma central sobre receptores alfa-2; la reserpina y la guanetidina bloquean neuronas adrenérgicas. Aunque el betabloqueo ya no es de primera línea en la hipertensión no complicada (se prefiere IECA, ARA II, calcioantagonistas y tiazidas), sigue indicado tras el infarto, en insuficiencia cardiaca con FE reducida (bisoprolol, carvedilol, metoprolol succinato) y en arritmias. El atenolol se ajusta en insuficiencia renal.",
  f="ACC/AHA, guía de hipertensión arterial (2025); ESC, guía de hipertensión arterial (2024); Katzung Farmacología Básica y Clínica 15.ª ed.")

Q(a="cardiologia", cat=None, tema="Primer mecanismo compensador en el shock", año=2014, ext=False,
  e="¿Cuál es el primer mecanismo compensador de la caída de presión arterial en el shock?",
  o=["Taquipnea.", "Taquicardia sinusal.", "Elevación del factor natriurético atrial.", "Elevación de renina.", "Aumento de la retención de sodio."], k="B",
  c="Ante la caída de la presión arterial, los barorreceptores del seno carotídeo y del arco aórtico reducen su descarga y, en segundos, el centro vasomotor bulbar activa el sistema simpático: aumentan la frecuencia cardiaca (taquicardia sinusal), la contractilidad y la vasoconstricción arterial y venosa, y se liberan adrenalina y noradrenalina. Es el mecanismo más rápido. En minutos a horas se activan el eje renina-angiotensina-aldosterona y la vasopresina (retención de sodio y agua), y en días la eritropoyetina y la reposición proteica. El factor natriurético atrial se eleva cuando hay sobrecarga de volumen, no en la hipovolemia. Clínica: la taquicardia es el signo más precoz de hemorragia, mientras que la hipotensión es tardía (en el adulto joven sano aparece cuando se pierde más del 30 % de la volemia, clase III de ATLS).",
  f="ATLS, 11.ª ed. (2025); Guyton y Hall Tratado de Fisiología Médica 14.ª ed.")

Q(a="cardiologia", cat=None, tema="Shock con gasto cardiaco bajo", año=2014, ext=False,
  e="Paciente con presión arterial media disminuida, pulso filiforme, extremidades frías y llenado capilar lento. El tipo de shock que presenta es con...",
  o=["Resistencia vascular sistémica baja.", "Gasto cardiaco alto.", "Gasto cardiaco bajo.", "Presión venosa central baja con gasto cardiaco alto.", "Resistencia vascular normal y gasto cardiaco alto."], k="C",
  c="El shock es un estado de hipoperfusión tisular con aporte de oxígeno insuficiente para las demandas metabólicas. Se clasifica en cuatro tipos: hipovolémico, cardiogénico, obstructivo (embolia pulmonar, taponamiento, neumotórax a tensión) y distributivo (séptico, anafiláctico, neurogénico). Los tres primeros son de gasto cardiaco bajo y se presentan con piel fría, pálida y sudorosa, pulso filiforme, llenado capilar lento y oliguria, con resistencia vascular sistémica compensatoriamente alta. El shock distributivo es de gasto alto y resistencias bajas: la piel está caliente (shock séptico temprano) y el pulso es saltón. La monitorización con catéter de Swan-Ganz o con ecografía cardiaca puntual (POCUS) permite diferenciar: presión de enclavamiento alta indica fallo cardiogénico, baja indica hipovolemia.",
  f="Surviving Sepsis Campaign (2021); ATLS 11.ª ed. (2025); Harrison Principios de Medicina Interna 22.ª ed.",
  nota="Se reemplazaron las opciones A, D por redacciones que no coincidan con el shock de bajo gasto (en el original «resistencia vascular alta» también era correcta).")

Q(a="nefrologia", cat=None, tema="Hiponatremia hipervolémica con sodio urinario bajo", año=2014, ext=False,
  e="Paciente de 55 años con anasarca, hiponatremia hipervolémica y concentración urinaria de sodio menor de 20 mmol/L. ¿Cuál es el diagnóstico más probable?",
  o=["Nefropatía perdedora de sal.", "Hipotiroidismo.", "Insuficiencia cardiaca.", "Secreción inapropiada de HAD.", "Falla renal aguda."], k="C",
  c="La hiponatremia hipervolémica aparece cuando hay exceso de agua corporal y de sodio total, con volumen circulante efectivo disminuido: insuficiencia cardiaca, cirrosis hepática y síndrome nefrótico. El riñón percibe hipovolemia efectiva, activa el sistema renina-angiotensina-aldosterona y la vasopresina (ADH), retiene sodio y agua y por eso el sodio urinario es bajo (< 20 mmol/L). Con anasarca, la causa más probable de las opciones es la insuficiencia cardiaca. En la pérdida renal de sal el sodio urinario es alto (> 20-40 mmol/L) con hipovolemia; en el SIADH el paciente es euvolémico con sodio urinario alto; en la falla renal aguda establecida también está alto. Tratamiento: restricción de agua y sodio, diuréticos de asa y tratar la causa; evitar la solución salina isotónica en exceso.",
  f="Guía europea de hiponatremia (ESE/ESICM/ERA-EDTA, 2014); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Signos de insuficiencia cardiaca derecha", año=2014, ext=False,
  e="¿Cuál de los siguientes hallazgos clínicos son más específicos de insuficiencia cardiaca derecha?",
  o=["Ingurgitación yugular, hepatomegalia y ascitis.", "Disnea paroxística nocturna, palpitaciones y tos.", "Síncope, angina y arritmia.", "Edema, hemoptisis y ortopnea.", "Nicturia, ictericia y hepatomegalia."], k="A",
  c="La falla del ventrículo derecho produce congestión venosa sistémica: ingurgitación yugular, reflujo hepatoyugular, hepatomegalia dolorosa, ascitis, derrame pleural y edema de miembros inferiores. La falla izquierda causa congestión pulmonar: disnea de esfuerzo, ortopnea, disnea paroxística nocturna, tos y estertores. En la práctica, la causa más frecuente de insuficiencia derecha es la insuficiencia izquierda (la fisiopatología de la falla biventricular), seguida del cor pulmonale por EPOC, hipertensión pulmonar y embolia pulmonar. La presión venosa yugular elevada y el reflujo hepatoyugular tienen buena especificidad para presiones de llenado altas. Orienta el tratamiento: diuréticos de asa, antagonistas de mineralocorticoides, y en la insuficiencia con FE reducida se añaden IECA/ARNI, betabloqueantes e iSGLT2 (ESC 2023).",
  f="ESC, guía de insuficiencia cardiaca (actualización 2023); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Soplo de Austin Flint", año=2014, ext=False,
  e="¿En qué patología valvular cardiaca se ausculta el soplo de Austin Flint?",
  o=["Estenosis mitral.", "Insuficiencia aórtica.", "Insuficiencia tricuspídea.", "Estenosis aórtica.", "Estenosis tricuspídea."], k="B",
  c="El soplo de Austin Flint es un retumbo mesodiastólico o presistólico apical que aparece en la insuficiencia aórtica grave: el chorro regurgitante golpea el velo anterior de la válvula mitral y lo hace vibrar, limitando parcialmente su apertura (estenosis mitral funcional). Se diferencia de la estenosis mitral orgánica porque no hay chasquido de apertura ni primer ruido intenso. Otros signos de insuficiencia aórtica: soplo diastólico aspirativo en el borde esternal izquierdo, presión de pulso amplia, pulso de Corrigan en martillo de agua, signo de Musset (cabeceo), pulso de Quincke (capilar) y signo de Duroziez. En la insuficiencia aórtica aguda, por ejemplo por endocarditis o disección, el cuadro es más grave porque el ventrículo no se ha dilatado: edema pulmonar y shock, y la cirugía es urgente.",
  f="ACC/AHA, guía de valvulopatías (2020); ESC/EACTS, guía de valvulopatías (2021); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Hallazgo ecocardiográfico del taponamiento", año=2014, ext=False,
  e="¿Cuál es el hallazgo ecocardiográfico que sugiere taponamiento cardiaco?",
  o=["Miocardio engrosado.", "Engrosamiento pericárdico.", "Calcificación pericárdica.", "Ventrículo derecho pequeño.", "Derrame pericárdico escaso."], k="D",
  c="El taponamiento cardiaco es un diagnóstico hemodinámico: la presión intrapericárdica supera la presión de las cámaras derechas, que son de baja presión, y las colapsa. En la ecocardiografía se ve colapso diastólico de la aurícula derecha (el signo más sensible) y del ventrículo derecho (el más específico), con ventrículo derecho pequeño, vena cava inferior dilatada sin variación respiratoria y variación respiratoria exagerada de los flujos mitral y tricuspídeo. La velocidad con que se acumula el líquido importa más que su cantidad: 150-200 mL de sangre súbitos (trauma o rotura) pueden causar taponamiento, mientras que 1 L de derrame crónico se tolera. Clínica: tríada de Beck (hipotensión, ingurgitación yugular y ruidos cardiacos apagados) y pulso paradójico. El tratamiento es la pericardiocentesis o la ventana pericárdica.",
  f="ESC, guía de enfermedades del pericardio (2015, vigente); ASE, ecocardiografía en el derrame pericárdico (2013); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="pediatria", cat=None, tema="Insuficiencia cardiaca en el lactante", año=2014, ext=False,
  e="En un lactante pequeño, ¿qué signos y síntomas son sospecha de insuficiencia cardiaca?",
  o=["Disnea y sudoración profusa al lactar.", "Hepatomegalia y distensión abdominal.", "Crepitantes y polipnea.", "Irritabilidad y cardiomegalia.", "Politirajes y aleteo nasal."], k="A",
  c="En el lactante la alimentación es el «ejercicio» que desencadena los síntomas: la insuficiencia cardiaca se manifiesta por disnea, sudoración profusa y cansancio durante la lactancia, tomas cortas y repetidas, mala ganancia de peso, taquipnea y taquicardia persistentes y hepatomegalia. A diferencia del adulto, la ortopnea y el edema de miembros son raros. Las causas más frecuentes son las cardiopatías congénitas con cortocircuito izquierda-derecha (comunicación interventricular, ductus arterioso persistente, canal auriculoventricular) que se hacen sintomáticas cuando baja la resistencia pulmonar (4-8 semanas); en las dos primeras semanas se piensa en lesiones ductodependientes (coartación crítica, hipoplasia de cavidades izquierdas). En adultos predominan la cardiopatía isquémica y la hipertensiva. Tratamiento: diuréticos, IECA, y corrección quirúrgica o percutánea.",
  f="Nelson Tratado de Pediatría 22.ª ed.; AHA/ACC, cardiopatías congénitas del adulto (2018)")

Q(a="cardiologia", cat=None, tema="Mejor marcador de infarto de miocardio", año=2014, ext=False,
  e="Varón de 62 años, hipertenso, presenta dolor torácico retroesternal y diaforesis. EKG: supradesnivel del segmento ST y ondas T negativas de V1 a V4. ¿Cuál es el mejor marcador cardiaco que confirma el diagnóstico de infarto de miocardio agudo?",
  o=["Troponina I.", "LDH.", "Mioglobina.", "CPK-MB.", "Péptido natriurético atrial."], k="A",
  c="Las troponinas cardiacas (I y T) son el biomarcador de elección para diagnosticar el infarto: son específicas del cardiomiocito, aparecen en sangre 2-4 horas tras la lesión (con los ensayos de alta sensibilidad se detectan desde la primera hora), alcanzan su pico a las 12-48 horas y se mantienen elevadas 7-14 días. La CPK-MB es menos específica y vuelve a lo normal en 48-72 horas, por lo que sirve para detectar reinfarto; la mioglobina sube rápido pero es muy inespecífica; la LDH es obsoleta. El péptido natriurético mide insuficiencia cardiaca. Importante: ante un STEMI el diagnóstico es clínico y electrocardiográfico y la reperfusión no debe esperar la troponina. La cuarta definición universal (2018) exige una elevación y/o caída de troponina con al menos un percentil 99 superior al límite, más isquemia clínica, electrocardiográfica o por imagen.",
  f="ESC, guía de síndromes coronarios agudos (2023); Cuarta Definición Universal del Infarto de Miocardio (2018); AHA/ACC, guía de dolor torácico (2021)")

Q(a="cardiologia", cat=None, tema="Factores de riesgo de arteriopatía coronaria", año=2014, ext=False,
  e="¿Cuáles son los factores de riesgo cardiovascular más importantes para la aparición de arteriopatía coronaria?",
  o=["Hipertensión arterial, diabetes mellitus, hiperlipidemia.", "Hipertensión arterial, diabetes mellitus, obesidad.", "Hipertensión arterial, tabaquismo, sedentarismo.", "Tabaquismo, diabetes mellitus, estrés.", "Estrés, tabaquismo, sedentarismo."], k="A",
  c="Los factores de riesgo cardiovascular se dividen en no modificables (edad, sexo masculino o menopausia, antecedentes familiares de enfermedad coronaria prematura) y modificables. Los de mayor peso poblacional (estudio INTERHEART) son la dislipidemia (relación ApoB/ApoA1 o LDL elevado), el tabaquismo, la hipertensión arterial y la diabetes mellitus, seguidos de obesidad abdominal, factores psicosociales, dieta pobre en frutas y verduras, falta de ejercicio y alcohol. La triada hipertensión, diabetes y dislipidemia es la más importante en la aterogénesis y la que más se emplea para estimar el riesgo (scores como SCORE2, Framingham o las ecuaciones de cohortes agrupadas). Metas: LDL < 70 mg/dL en prevención secundaria (< 55 mg/dL en riesgo muy alto según ESC 2019/2025) y PA < 130/80 mmHg en la mayoría.",
  f="ESC/EAS, guía de dislipidemias (2019, actualización focal 2025); ACC/AHA, guía de hipertensión (2025); estudio INTERHEART (Lancet 2004)")

Q(a="cardiologia", cat=None, tema="Enzima que se eleva en el infarto de miocardio", año=2014, ext=False,
  e="¿Cuál de las siguientes enzimas se incrementa durante el infarto agudo de miocardio?",
  o=["Creatinfosfoquinasa.", "Fosfolipasa.", "Fosfoquinasa.", "Gammaglutamiltransferasa.", "Fosforilasa."], k="A",
  c="La creatinfosfoquinasa (CK) se libera del músculo estriado y de los cardiomiocitos dañados; su fracción MB (CK-MB) es más específica del corazón, sube a las 3-6 horas, alcanza el pico a las 12-24 horas y se normaliza en 48-72 horas. La gamma-glutamil transferasa es un marcador de colestasis y consumo de alcohol; la fosfolipasa participa en la pancreatitis y en la señalización celular; la fosforilasa y la fosfoquinasa intervienen en el metabolismo del glucógeno. Aunque históricamente la CK-MB era el marcador estándar, hoy el marcador recomendado es la troponina cardiaca de alta sensibilidad. La CK-MB conserva utilidad para fechar un infarto reciente y para detectar reinfarto precoz.",
  f="Cuarta Definición Universal del Infarto de Miocardio (2018); ESC, síndromes coronarios agudos (2023); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Eje eléctrico en la hipertrofia ventricular izquierda", año=2014, ext=False,
  e="Varón de 75 años con diagnóstico de hipertensión arterial severa desde hace 15 años. Electrocardiograma: hipertrofia ventricular izquierda. ¿En cuál de los siguientes grados se encuentra el eje del vector del QRS?",
  o=["+30º.", "+120º.", "-150º.", "-60º.", "+90º."], k="D",
  c="El eje eléctrico normal del QRS va de -30° a +90° (algunos autores hasta +110°). En la hipertrofia del ventrículo izquierdo la masa muscular aumentada desvía el eje hacia la izquierda, con un eje de -30° a -90° (desviación izquierda). Otras causas de desviación izquierda: hemibloqueo anterior izquierdo, infarto inferior (ondas Q en D2, D3, aVF), bloqueo de rama izquierda, Wolff-Parkinson-White y cardiopatías congénitas como la atresia tricuspídea. El eje desviado a la derecha (> +110°) se ve en hipertrofia del ventrículo derecho, embolia pulmonar, EPOC, hemibloqueo posterior y dextrocardia. Se calcula mirando el QRS en D1 y aVF: ambos positivos, eje normal; D1 positivo y aVF negativo, desviación izquierda; D1 negativo y aVF positivo, desviación derecha. Criterios de HVI: Sokolow-Lyon (S en V1 + R en V5 o V6 ≥ 35 mm) y Cornell.",
  f="AHA/ACC/HRS, estandarización e interpretación del ECG (2009); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Contraindicación absoluta de fibrinólisis", año=2014, ext=False,
  e="Varón de 55 años acude a emergencia con síntomas compatibles de infarto de miocardio y bloqueo de rama izquierda de novo. Si se requiere iniciar terapia fibrinolítica, ¿cuál sería la contraindicación absoluta?",
  o=["Hipertensión grave no controlada.", "Punciones vasculares.", "Antecedente de úlcera péptica.", "Neoplasia intracraneal.", "Reanimación cardiopulmonar prolongada."], k="D",
  c="El bloqueo de rama izquierda nuevo en un cuadro de dolor torácico se trata como un infarto con elevación del ST: reperfusión urgente, de preferencia con angioplastia primaria en menos de 120 minutos; si no es posible, fibrinólisis lo antes posible (idealmente en ≤ 10 min del diagnóstico según ESC, ≤ 30 min de la llegada según AHA). Contraindicaciones absolutas (ESC 2023): hemorragia intracraneal previa, ictus isquémico en los 6 meses previos, neoplasia o malformación vascular del sistema nervioso central, traumatismo mayor o cirugía en el último mes, sangrado gastrointestinal en el último mes, trastorno hemorrágico conocido y disección aórtica. La hipertensión grave no controlada (> 180/110) y la reanimación prolongada son contraindicaciones relativas. Tras la fibrinólisis se debe trasladar a un centro con angioplastia para coronariografía a las 2-24 horas.",
  f="ESC, guía de síndromes coronarios agudos (2023); AHA/ACC, guía de revascularización coronaria (2021)",
  )

Q(a="cardiologia", cat=None, tema="Estenosis aórtica: síncope en el anciano", año=2014, ext=False,
  e="Varón de 80 años acude a emergencia por presentar síncope mientras subía la escalera. Examen físico: soplo sistólico eyectivo III/VI. Electrocardiograma: ritmo sinusal normal con signos de hipertrofia del ventrículo izquierdo. ¿Cuál es el diagnóstico más probable?",
  o=["Estenosis aórtica.", "Insuficiencia aórtica.", "Insuficiencia mitral.", "Estenosis mitral.", "Comunicación interventricular."], k="A",
  c="La estenosis aórtica calcificada, la valvulopatía más frecuente del anciano en países desarrollados, produce la tríada clásica de angina, síncope de esfuerzo y disnea. El soplo es sistólico eyectivo, de timbre áspero, con foco aórtico e irradiado a las carótidas, y se acompaña de pulso parvus et tardus y segundo ruido disminuido. El electrocardiograma muestra hipertrofia del ventrículo izquierdo, y el ecocardiograma confirma el diagnóstico y mide el área valvular (< 1 cm², gradiente medio ≥ 40 mmHg, velocidad máxima ≥ 4 m/s). Una vez aparecen los síntomas, la supervivencia sin tratamiento es de 2-3 años: está indicado el reemplazo valvular, quirúrgico o transcatéter (TAVI). En el estudio de síncope por esfuerzo está contraindicada la prueba de esfuerzo si hay estenosis grave sintomática.",
  f="ACC/AHA, guía de valvulopatías (2020); ESC/EACTS, guía de valvulopatías (2021); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="neumologia", cat=None, tema="Língula: lóbulo superior izquierdo", año=2014, ext=False,
  e="Paciente que en la radiografía de tórax presenta tumoración a nivel de la língula. ¿En qué lóbulo se encuentra la lesión?",
  o=["Superior derecho.", "Inferior derecho.", "Superior izquierdo.", "Medio derecho.", "Inferior izquierdo."], k="C",
  c="El pulmón derecho tiene tres lóbulos (superior, medio e inferior) separados por las cisuras horizontal y oblicua, y 10 segmentos broncopulmonares. El pulmón izquierdo tiene dos lóbulos (superior e inferior) separados por la cisura oblicua y 8-10 segmentos. La língula es una porción del lóbulo superior izquierdo, equivalente anatómico del lóbulo medio derecho, formada por los segmentos lingulares superior e inferior (segmentos 4 y 5). En la radiografía de tórax, una opacidad que borra el borde izquierdo del corazón («signo de la silueta») localiza la lesión en la língula, y una que borra el borde derecho cardiaco, en el lóbulo medio. El hilio izquierdo está más alto que el derecho. Por su orientación y calibre, el lóbulo medio y la língula son propensos al colapso por bronquiectasias o linfadenopatías (síndrome del lóbulo medio).",
  f="Moore Anatomía con orientación clínica 8.ª ed.; Fraser y Paré Diagnosis of Diseases of the Chest 5.ª ed.")

Q(a="cirugia", cat=None, tema="Radiografía en lesión de grandes vasos por trauma", año=2014, ext=False,
  e="¿Cuál de los siguientes datos radiográficos sugiere lesión de grandes vasos en el traumatismo de tórax?",
  o=["Hemotórax.", "Neumotórax.", "Desviación de la tráquea.", "Enfisema subcutáneo.", "Ensanchamiento del mediastino."], k="E",
  c="El ensanchamiento del mediastino (> 8 cm a nivel del botón aórtico en una radiografía AP) es el signo radiográfico más sensible de lesión de la aorta torácica o de grandes vasos (rotura traumática del istmo aórtico en la desaceleración). Otros signos: borramiento del botón aórtico, desviación de la tráquea o de la sonda nasogástrica a la derecha, descenso del bronquio principal izquierdo, casquete pleural apical y fractura de las primeras costillas o de la escápula. Estos hallazgos obligan a realizar una angiotomografía de aorta; la mortalidad inmediata es del 80 %, y los que llegan vivos tienen una pared adventicial contenida que debe tratarse con reparación endovascular (TEVAR) en lugar de cirugía abierta. El hemotórax y el neumotórax orientan a lesiones pleuropulmonares; el enfisema subcutáneo, a fuga aérea.",
  f="ATLS, 11.ª ed. (2025); SVS, guía de lesión traumática de la aorta torácica (2011, TEVAR); Schwartz Principios de Cirugía 11.ª ed.")

Q(a="neumologia", cat=None, tema="Causa más frecuente de quilotórax", año=2014, ext=False,
  e="¿Cuál es la causa más frecuente de quilotórax?",
  o=["Traumatismo.", "Tumores mediastinales.", "Pancreatitis aguda necrotizante.", "Embolia grasa.", "TBC pulmonar exudativa."], k="A",
  c="El quilotórax es la acumulación de quilo (linfa intestinal rica en triglicéridos y quilomicrones) en el espacio pleural por lesión u obstrucción del conducto torácico. Es un líquido lechoso con triglicéridos > 110 mg/dL (el pseudoquilotórax es un derrame crónico con colesterol alto y triglicéridos bajos, como en la tuberculosis o la artritis reumatoide). La causa más frecuente en general es traumática, en especial iatrogénica (cirugía esofágica, cardiaca o torácica); las causas no traumáticas más frecuentes son las neoplasias, sobre todo los linfomas. Tratamiento: dieta sin grasas de cadena larga o nutrición parenteral, octreótido, drenaje y, si el drenaje es mayor de 1000 mL/día por 5 días o persiste más de 2 semanas, ligadura quirúrgica del conducto torácico.",
  f="Light Pleural Diseases 6.ª ed.; Fishman Pulmonary Diseases and Disorders 5.ª ed.")

Q(a="cirugia", cat=None, tema="Estudio del sistema venoso de miembros inferiores", año=2014, ext=False,
  e="¿Cuál de los siguientes estudios está indicado para evaluar la insuficiencia valvular y la obstrucción venosa de miembros inferiores?",
  o=["Eco Doppler.", "Captación de fibrinógeno con yodo 125.", "Impedancia.", "Flebografía.", "Resonancia magnética."], k="A",
  c="El eco Doppler venoso (ecografía dúplex) es el estudio de elección para evaluar el sistema venoso superficial, profundo y perforante de los miembros inferiores: demuestra la compresibilidad de las venas (ausente en la trombosis), el flujo espontáneo y fásico, y el reflujo valvular tras maniobras de compresión (reflujo patológico > 0,5 s en venas superficiales y > 1 s en venas profundas). Detecta tanto obstrucción (trombosis venosa profunda) como insuficiencia valvular (várices, síndrome posflebítico). La flebografía es invasiva y quedó reservada para casos dudosos o cirugía; la pletismografía de impedancia y la captación de fibrinógeno marcado con yodo-125 están en desuso; la RM venosa se usa para venas pélvicas o la cava. Clasificación CEAP para la enfermedad venosa crónica (C0 a C6).",
  f="SVS/AVF, guía de enfermedad venosa crónica (2011); ESVS, guía de enfermedad venosa crónica (2022)")

Q(a="ciencias_basicas", cat="Histología y Biología Celular", tema="Adventicia con tejido conjuntivo laxo", año=2014, ext=False,
  e="La túnica adventicia tiene tejido conjuntivo laxo en:",
  o=["Arteriolas.", "Arterias elásticas.", "Arterias musculares.", "Venas grandes.", "Vénulas."], k="A",
  c="Todos los vasos sanguíneos, salvo los capilares, tienen tres túnicas: íntima (endotelio y lámina subendotelial), media (músculo liso y elásticas) y adventicia (tejido conjuntivo con fibras colágenas y elásticas, fibroblastos, vasa vasorum y nervios). En las arteriolas la adventicia es delgada y formada por tejido conjuntivo laxo, y su media tiene una a tres capas de músculo liso: son los vasos de resistencia que regulan la presión arterial y el flujo tisular. En las arterias elásticas (aorta) y musculares la adventicia es más gruesa, con vasa vasorum que nutren la pared; en las venas grandes es la túnica más gruesa y con haces de músculo liso longitudinal. Por eso la hipertensión afecta sobre todo a la media de las arteriolas, que se engruesa (hialinosis y arterioloesclerosis hiperplásica).",
  f="Ross Histología. Texto y Atlas 8.ª ed.; Junqueira Histología Básica 13.ª ed.",
  nota="Pregunta de histología con redacción poco precisa; se mantiene la clave del libro.")

Q(a="ciencias_basicas", cat="Histología y Biología Celular", tema="Túnica media y resistencia vascular", año=2014, ext=True,
  e="¿Cuál de las siguientes capas o túnicas de las arteriolas intervienen en la regulación de la resistencia vascular periférica?",
  o=["Adventicia.", "Elástica externa.", "Elástica interna.", "Endotelio.", "Media."], k="E",
  c="La túnica media de las arteriolas contiene células musculares lisas dispuestas circularmente cuya contracción o relajación cambia el diámetro luminal y, según la ley de Poiseuille (resistencia inversamente proporcional a la cuarta potencia del radio), la resistencia vascular periférica. El control es nervioso (simpático, receptores alfa-1), humoral (angiotensina II, vasopresina, adrenalina) y local (óxido nítrico, adenosina, CO₂, hipoxia). El endotelio libera sustancias vasoactivas que modulan el tono, pero el efector mecánico es el músculo de la media. Las arteriolas aportan alrededor del 50 % de la resistencia total al flujo y por eso son el blanco de los vasodilatadores (hidralazina, calcioantagonistas, nitroprusiato), mientras que los nitratos actúan sobre todo en venas.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Ross Histología. Texto y Atlas 8.ª ed.")

Q(a="cardiologia", cat=None, tema="Edema periférico por fármacos", año=2015, ext=False,
  e="Varón de 60 años consulta por presentar desde hace 2 meses edema de miembros inferiores. Como antecedente fue diagnosticado de HTA y obesidad hace 3 meses y le indican atorvastatina, ácido acetil salicílico, amlodipino, metformina e hidroclorotiazida. ¿Cuál de los fármacos que recibe es el causante del edema que presenta el paciente?",
  o=["Atorvastatina.", "Ácido acetil salicílico.", "Metformina.", "Amlodipino.", "Hidroclorotiazida."], k="D",
  c="El edema periférico, dependiente de la dosis, es el efecto adverso más frecuente de los calcioantagonistas dihidropiridínicos (amlodipino, nifedipino, felodipino). Se debe a una vasodilatación arteriolar precapilar sin dilatación venosa equivalente: aumenta la presión hidrostática capilar y el líquido sale al intersticio, sin retención de sodio ni insuficiencia cardiaca. Aparece en tobillos y piernas, empeora al final del día y no responde a diuréticos; mejora si se añade un IECA o un ARA II (dilatan la arteriola eferente y la vénula), se reduce la dosis o se cambia de fármaco. Las estatinas causan mialgias y elevación de transaminasas, la aspirina gastritis y sangrado, la metformina síntomas digestivos y acidosis láctica, y la hidroclorotiazida más bien reduce el edema.",
  f="ACC/AHA, guía de hipertensión (2025); Katzung Farmacología Básica y Clínica 15.ª ed.")

Q(a="cardiologia", cat=None, tema="Pulso paradójico en el taponamiento traumático", año=2015, ext=False,
  e="El taponamiento pericárdico traumático se caracteriza clínicamente por:",
  o=["Hipotensión ortostática.", "Pulso paradójico.", "Ruidos cardiacos aumentados.", "Ansiedad y sudoración.", "Bradicardia persistente."], k="B",
  c="El pulso paradójico es una caída de la presión arterial sistólica mayor de 10 mmHg durante la inspiración. En condiciones normales la inspiración aumenta el retorno venoso al corazón derecho y la presión sistólica baja unos 3-5 mmHg. En el taponamiento, el pericardio lleno de líquido limita el volumen total del corazón, el ventrículo derecho dilatado desplaza el tabique hacia la izquierda en la inspiración y el ventrículo izquierdo se llena menos: cae el gasto y la presión. La tríada de Beck (hipotensión, ingurgitación yugular y ruidos cardiacos apagados, no aumentados) acompaña al pulso paradójico. Otras causas de pulso paradójico: asma grave, EPOC, embolia pulmonar y pericarditis constrictiva. En el trauma penetrante precordial, la FAST o ecografía pericárdica confirma el hemopericardio y el tratamiento es la toracotomía o esternotomía, no la pericardiocentesis.",
  f="ATLS, 11.ª ed. (2025); ESC, enfermedades del pericardio (2015); Schwartz Principios de Cirugía 11.ª ed.")

Q(a="ciencias_basicas", cat="Fisiología", tema="Fibras de Purkinje", año=2015, ext=False,
  e="¿Cuáles son las estructuras que se dirigen desde el nódulo AV hacia los ventrículos siendo estas mayormente grandes y de rápida transmisión, con respecto a otras estructuras?",
  o=["Nervios simpáticos.", "Haz AV derecho.", "Fibras de Purkinje.", "Fibras del nódulo AV.", "Fibras musculares lisas."], k="C",
  c="El impulso nace en el nodo sinusal, recorre la aurícula y llega al nodo auriculoventricular, donde se retarda unos 0,1 s (conducción lenta que permite que los ventrículos se llenen). Luego pasa al haz de His, que se divide en rama derecha e izquierda (esta con fascículos anterior y posterior), y termina en la red de Purkinje subendocárdica. Las fibras de Purkinje son las de mayor diámetro y las de conducción más rápida del corazón (1,5-4 m/s, unas seis veces más que el miocardio contráctil), por lo que activan casi de forma simultánea el endocardio de ambos ventrículos y producen una contracción coordinada con QRS estrecho. Un bloqueo de rama ensancha el QRS (> 120 ms) porque el impulso viaja lentamente por el miocardio.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Boron y Boulpaep Fisiología Médica 3.ª ed.")

Q(a="cardiologia", cat=None, tema="Taquicardia supraventricular sin compromiso hemodinámico", año=2015, ext=False,
  e="En el tratamiento agudo de taquicardia paroxística supraventricular (TPSV) sin compromiso hemodinámico, ¿cuál es el fármaco de elección?",
  o=["Lidocaína.", "Adenosina.", "Atropina.", "Amiodarona.", "Quinidina."], k="B",
  c="La taquicardia paroxística supraventricular más frecuente es la reentrada intranodal, seguida de la que utiliza una vía accesoria. Tiene QRS estrecho, regular y frecuencia de 150-250 lpm. El tratamiento en un paciente estable empieza con maniobras vagales (Valsalva modificada, que tiene mayor éxito que el masaje carotídeo) y, si no ceden, adenosina intravenosa en bolo rápido (6 mg y luego 12 mg), que bloquea transitoriamente el nodo auriculoventricular y revierte la reentrada en más del 90 %. Efectos transitorios: rubor, opresión torácica y pausa breve. Si fracasa se usa verapamilo o diltiazem (si no hay insuficiencia cardiaca) o un betabloqueante. Con inestabilidad hemodinámica se realiza cardioversión eléctrica sincronizada. La lidocaína y la atropina no tienen indicación; la amiodarona queda como último recurso.",
  f="AHA/ACC/HRS, guía de taquicardia supraventricular (2015); ESC, guía de taquicardia supraventricular (2019)")

Q(a="cardiologia", cat=None, tema="Disnea y dolor torácico en el adulto mayor con factores de riesgo", año=2015, ext=False,
  e="Varón de 67 años presenta falta de aire de inicio abrupto posterior a esfuerzo físico, refiere dolor leve retroesternal, con antecedente de 3 episodios de dolor opresivo en el pecho de intensidad moderada en el último año, presenta sobrepeso. Examen: orientado, lúcido. FC: 100 x min, PA: 96/60 mmHg, segundo ruido con aumento moderado de intensidad. Pulmones: murmullo vesicular audible en ambos campos pulmonares, sin ruidos agregados. Resto del examen normal. ¿El enfoque del padecimiento del paciente es de naturaleza?",
  o=["Cardíaca.", "Pulmonar.", "Psiquiátrica.", "Hipoventilatoria.", "Tromboembolismo."], k="A",
  c="Un varón mayor, con sobrepeso, que tuvo episodios previos de dolor opresivo (probable angina) y consulta por disnea súbita tras esfuerzo con dolor retroesternal, taquicardia e hipotensión leve, plantea como primera hipótesis un síndrome coronario agudo o una falla cardiaca por isquemia. El examen pulmonar sin estertores ni sibilancias hace menos probable una causa pulmonar primaria; el aumento del segundo ruido podría sugerir hipertensión pulmonar (embolia), pero la anamnesis apunta al origen cardiaco. Conducta: ECG de 12 derivaciones en menos de 10 minutos, troponina de alta sensibilidad en serie, aspirina y monitorización. La pregunta es de razonamiento clínico («de naturaleza cardiaca, isquémica»), y el libro la reconoce como controversial por falta de datos de ECG y enzimas.",
  f="ESC, guía de síndromes coronarios agudos (2023); AHA/ACC, guía de dolor torácico (2021)",
  nota="Pregunta controversial según el libro; se mantiene la clave.")
